import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { ApplicationDetails } from 'src/app/auth/Models/ApplicationDetails';
import { Company } from 'src/app/landing/models/company';
import { ApplicationService } from 'src/app/service/application/application.service';
import { CompanyService } from 'src/app/service/company/company.service';
import { AuthStateService } from 'src/app/shared/services/auth-state.service';

@Component({
  selector: 'app-review',
  templateUrl: './review.component.html',
  styleUrls: ['./review.component.css']
})
export class ReviewComponent implements OnInit {
  company!: Company;
  app!: ApplicationDetails;

  constructor(
    private readonly compService: CompanyService,
    private readonly appService: ApplicationService,
    private readonly route: ActivatedRoute,
    private readonly authState: AuthStateService
  ) {}

  ngOnInit(): void {
    const companyId = Number(this.route.snapshot.paramMap.get('id') ?? this.authState.id ?? 0);
    const appId = Number(this.route.snapshot.paramMap.get('appId') ?? 0);

    if (companyId > 0) {
      this.compService.getCompanyById(companyId).subscribe((res: Company) => (this.company = res));
    }
    if (appId > 0) {
      this.appService.getApplicationById(appId).subscribe((res: ApplicationDetails) => (this.app = res));
    }
  }

  get avatar(): string {
    return this.authState.initialsFromCompany(this.company);
  }

  rejectApplication(): void {
    const appId = Number(this.route.snapshot.paramMap.get('appId') ?? 0);
    if (appId > 0) {
      this.appService.rejectApplication(appId).subscribe((res: ApplicationDetails) => (this.app = res));
    }
  }

  approveApplication(): void {
    const appId = Number(this.route.snapshot.paramMap.get('appId') ?? 0);
    if (appId > 0) {
      this.appService.approveApplication(appId).subscribe((res: ApplicationDetails) => (this.app = res));
    }
  }
}
